/**
 * frontend/src/App.jsx - REMPLACER
 * Avec authentification intégrée
 */

import React, { useState, useEffect } from 'react';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import Login from './pages/Login';
import authService from './auth_service';

const COLORS = {
  primary: '#4F46E5',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  sidebar: '#1E293B'
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  // Initialize auth on mount
  useEffect(() => {
    authService.initialize();

    if (authService.isAuthenticated()) {
      const user = authService.getUser();
      setCurrentUser(user);
      setIsAuthenticated(true);
    }

    setLoading(false);
  }, []);

  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addNotification(`✅ Bienvenue, ${user.first_name || user.username}!`, 'success');
  };

  const handleLogout = async () => {
    await authService.logout();
    setCurrentUser(null);
    setIsAuthenticated(false);
    setCurrentView('dashboard');
    addNotification('✅ Vous avez été déconnecté', 'info');
  };

  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 4000);
  };

  if (loading) {
    return <div style={styles.loading}>⏳ Chargement...</div>;
  }

  // Show login if not authenticated
  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={styles.appWrapper}>
      {/* Sidebar */}
      <aside style={styles.sidebar}>
        <div style={styles.brand}>
          <div style={styles.brandIcon}>Σ</div>
          <h2 style={styles.brandName}>Attendance OS</h2>
        </div>

        <nav style={styles.sideNav}>
          <NavItem
            active={currentView === 'dashboard'}
            onClick={() => setCurrentView('dashboard')}
            icon="📊"
            label="Dashboard"
          />
          <NavItem
            active={currentView === 'enrollment'}
            onClick={() => setCurrentView('enrollment')}
            icon="➕"
            label="Enrôlement"
          />
          <NavItem
            active={currentView === 'camera'}
            onClick={() => setCurrentView('camera')}
            icon="📷"
            label="Reconnaissance"
          />
        </nav>

        <div style={styles.userProfile}>
          <div style={styles.avatar}>
            {currentUser?.first_name?.[0] || currentUser?.username?.[0] || 'U'}
          </div>
          <div>
            <div style={styles.userName}>
              {currentUser?.first_name || currentUser?.username}
            </div>
            <div style={styles.userRole}>Admin</div>
          </div>
        </div>

        <button
          onClick={handleLogout}
          style={styles.logoutBtn}
        >
          🚪 Déconnexion
        </button>
      </aside>

      {/* Main Content */}
      <main style={styles.main}>
        <header style={styles.topBar}>
          <div style={styles.searchBar}>
            <span>🔍</span>
            <input
              style={styles.searchInput}
              placeholder="Rechercher un étudiant..."
            />
          </div>
          <div style={styles.topActions}>
            <button style={styles.iconBtn}>🔔</button>
            <button style={styles.iconBtn}>⚙️</button>
          </div>
        </header>

        <div style={styles.content}>
          <header style={styles.pageHeader}>
            <h1 style={styles.pageTitle}>
              {currentView === 'dashboard' && 'Vue d\'ensemble'}
              {currentView === 'enrollment' && 'Nouvel Étudiant'}
              {currentView === 'camera' && 'Reconnaissance en direct'}
            </h1>
            <p style={styles.pageSubtitle}>
              Système de surveillance biométrique actif
            </p>
          </header>

          {currentView === 'dashboard' && <Dashboard />}
          {currentView === 'enrollment' && (
            <Enrollment
              onSuccess={() =>
                addNotification('✅ Étudiant enrôlé avec succès!', 'success')
              }
            />
          )}
          {currentView === 'camera' && <CameraRecognition />}
        </div>
      </main>

      {/* Notifications */}
      <div style={styles.toastContainer}>
        {notifications.map(notif => (
          <Toast key={notif.id} message={notif.message} type={notif.type} />
        ))}
      </div>

      {/* Global Styles */}
      <style>{`
        @keyframes slideIn {
          from {
            transform: translateX(400px);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }

        * {
          box-sizing: border-box;
        }

        body {
          margin: 0;
          font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
          background-color: ${COLORS.background};
        }

        input, select, textarea {
          font-family: inherit;
        }

        input:focus, select:focus, textarea:focus {
          outline: none;
        }

        button:hover {
          opacity: 0.9;
        }

        button:disabled {
          cursor: not-allowed;
        }
      `}</style>
    </div>
  );
};

const NavItem = ({ active, icon, label, onClick }) => (
  <div
    onClick={onClick}
    style={{
      ...styles.navItem,
      backgroundColor: active ? COLORS.primary + '15' : 'transparent',
      color: active ? COLORS.primary : COLORS.textMuted,
      borderLeft: active ? `4px solid ${COLORS.primary}` : '4px solid transparent'
    }}
  >
    <span style={styles.navIcon}>{icon}</span>
    {label}
  </div>
);

const Toast = ({ message, type }) => {
  const bgColor = {
    success: '#DCFCE7',
    error: '#FEE2E2',
    info: '#DBEAFE',
    warning: '#FEF3C7'
  }[type] || '#F1F5F9';

  const textColor = {
    success: '#166534',
    error: '#991B1B',
    info: '#0C4A6E',
    warning: '#92400E'
  }[type] || '#475569';

  return (
    <div
      style={{
        ...styles.toast,
        backgroundColor: bgColor,
        color: textColor
      }}
    >
      {message}
    </div>
  );
};

